// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        vm.deal(address(this), 1 ether);
        (bool success, ) = address(c).call{value: 1 wei}("");
        require(success, "receive failed");
        address target = address(this);
        c.sendMoney(target, 1 wei);
        assertTrue(c.depositsCount() == 1);
    }
}
